create extension if not exists pgcrypto;

create table if not exists public.profiles (id uuid primary key references auth.users(id) on delete cascade,display_name text,role text not null default 'ADMIN' check (role in ('ADMIN','CONTROL','VIEW_ONLY')),created_at timestamptz not null default now());
create table if not exists public.devices (id uuid primary key default gen_random_uuid(),owner_id uuid not null references auth.users(id) on delete cascade,name text not null,token_hash text not null unique,agent_version text,windows_version text,last_seen timestamptz,status text not null default 'OFFLINE' check (status in ('ONLINE','WARNING','OFFLINE')),created_at timestamptz not null default now());
create table if not exists public.device_status (device_id uuid primary key references public.devices(id) on delete cascade,cpu_percent numeric,ram_percent numeric,ram_used_bytes bigint,ram_total_bytes bigint,disk_percent numeric,disk_free_bytes bigint,disk_total_bytes bigint,uptime_seconds bigint,battery_percent numeric,battery_plugged boolean,internet_ok boolean,shutdown_due_at timestamptz,shutdown_action text check (shutdown_action is null or shutdown_action in ('SHUTDOWN','RESTART')),updated_at timestamptz not null default now());
create table if not exists public.device_commands (id uuid primary key default gen_random_uuid(),device_id uuid not null references public.devices(id) on delete cascade,created_by uuid not null references auth.users(id) on delete cascade,command text not null check (command in ('LOCK','SLEEP','HIBERNATE','RESTART','SHUTDOWN','CANCEL_SHUTDOWN')),parameters jsonb not null default '{}'::jsonb,status text not null default 'PENDING' check (status in ('PENDING','RECEIVED','RUNNING','SUCCESS','FAILED','EXPIRED','REJECTED')),created_at timestamptz not null default now(),expires_at timestamptz not null default (now()+interval '60 seconds'),received_at timestamptz,executed_at timestamptz,result jsonb,error_message text);
create table if not exists public.device_events (id bigint generated by default as identity primary key,device_id uuid not null references public.devices(id) on delete cascade,user_id uuid references auth.users(id) on delete set null,event_type text not null,message text not null,result text,created_at timestamptz not null default now());
create index if not exists idx_device_commands_pending on public.device_commands(device_id,status,created_at);
create index if not exists idx_device_events_recent on public.device_events(device_id,created_at desc);
alter publication supabase_realtime add table public.devices;
alter publication supabase_realtime add table public.device_status;
alter publication supabase_realtime add table public.device_commands;
alter publication supabase_realtime add table public.device_events;
